#!/bin/sh
set -eu
package_dir=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
build_dir=$(mktemp -d "${TMPDIR:-/tmp}/awc-native-views.XXXXXX")
trap 'rm -rf "$build_dir"' EXIT HUP INT TERM
# Optional SwiftPM flags, such as --scratch-path, are forwarded unchanged.
swift build --package-path "$package_dir" "$@"
library_dir=$(swift build --package-path "$package_dir" --show-bin-path "$@")
# Reuse the compiler's content-keyed module cache across focused runs. Test
# executables remain isolated; the cache lives only in ignored build output.
module_cache_dir=${AWC_NATIVE_TEST_MODULE_CACHE:-"$package_dir/.build/native-view-module-cache"}
mkdir -p "$module_cache_dir"
# Optional focused runs keep the same checked-in compile/runtime path as the full suite.
for fixture in ${AWC_NATIVE_VIEW_FIXTURES:-NativeToolbarStatesIntegration NativeToolbarPaintIntegration NativeMenuStatesIntegration NativeMenuPaintIntegration NativeBehaviorViewIntegration NativeNavigationBarStatesIntegration NativeNavigationBarPaintIntegration NativeTabsStatesIntegration NativeTabsPaintIntegration NativeBreadcrumbsStatesIntegration NativeBreadcrumbsPaintIntegration NativeSliderRatingIntegration NativeStepperIntegration NativeRippleIntegration NativeFocusViewIntegration NativeButtonAppearanceViewIntegration NativeInspectionViewIntegration NativeIconButtonViewIntegration NativeButtonGroupViewIntegration NativeFabViewIntegration NativeFabMenuLifecycleIntegration NativeFabMenuViewIntegration NativeSegmentedViewIntegration NativeSplitButtonViewIntegration NativeLoadingIndicatorViewIntegration NativeMeterViewIntegration NativeProgressIndicatorViewIntegration NativeSkeletonViewIntegration NativeSnackbarControllerIntegration NativeSnackbarViewIntegration NativeTooltipControllerIntegration NativeTooltipViewIntegration NativeAccordionStateIntegration NativeAccordionBrowserStateIntegration NativeAccordionMotionIntegration NativeAccordionRendererIntegration NativeAccordionInitializationIntegration NativeAccordionScrollingIntegration NativeAccordionAppearanceIntegration NativeAccordionPartsIntegration NativeAccordionReorderIntegration NativeAccordionLiftIntegration NativeAccordionShiftIntegration NativeAccordionStatesIntegration NativeAccordionPlaceholderIntegration NativeAccordionFloatingIntegration NativeCardPaintIntegration NativeCardStatesIntegration NativeCardLifecycleIntegration NativeListMethodsIntegration NativeListPaintIntegration NativeListStatesIntegration NativeListTooltipIntegration NativeBottomSheetMotionIntegration NativeBottomSheetPaintIntegration NativeDialogMotionIntegration NativeDialogPaintIntegration NativeModalStackIntegration NativeSideSheetMotionIntegration NativeSideSheetPaintIntegration NativeAvatarIntegration NativeSwitchPaintIntegration NativeSwitchStatesIntegration NativeCheckboxPaintIntegration NativeCheckboxStatesIntegration NativeChipPaintIntegration NativeChipStatesIntegration NativeButtonPaintIntegration NativeButtonStatesIntegration NativeRadioPaintIntegration NativeRadioStatesIntegration NativeTextFieldPaintIntegration NativeTextFieldStatesIntegration NativeNumberFieldPaintIntegration NativeNumberFieldStatesIntegration NativeOTPFieldPaintIntegration NativeOTPFieldStatesIntegration NativeOrgChartPaintIntegration NativeOrgChartStatesIntegration NativeThemeIntegration}; do
  case "$fixture" in
    NativeColorPickerPaintIntegration|NativeColorPickerStatesIntegration|NativeRippleIntegration|NativeBreadcrumbsPaintIntegration|NativeBreadcrumbsStatesIntegration|NativeSliderRatingIntegration|NativeStepperIntegration|NativeTabsPaintIntegration|NativeTabsStatesIntegration|NativeNavigationBarPaintIntegration|NativeNavigationBarStatesIntegration|NativeMenuPaintIntegration|NativeMenuStatesIntegration|NativeToolbarPaintIntegration|NativeToolbarStatesIntegration|NativeBehaviorViewIntegration|NativeFocusViewIntegration|NativeButtonAppearanceViewIntegration|NativeInspectionViewIntegration|NativeIconButtonViewIntegration|NativeButtonGroupViewIntegration|NativeFabViewIntegration|NativeFabMenuLifecycleIntegration|NativeFabMenuViewIntegration|NativeSegmentedViewIntegration|NativeSplitButtonViewIntegration|NativeLoadingIndicatorViewIntegration|NativeMeterViewIntegration|NativeProgressIndicatorViewIntegration|NativeSkeletonViewIntegration|NativeSnackbarControllerIntegration|NativeSnackbarViewIntegration|NativeTooltipControllerIntegration|NativeTooltipViewIntegration|NativeAccordionStateIntegration|NativeAccordionBrowserStateIntegration|NativeAccordionMotionIntegration|NativeAccordionRendererIntegration|NativeAccordionInitializationIntegration|NativeAccordionScrollingIntegration|NativeAccordionAppearanceIntegration|NativeAccordionPartsIntegration|NativeAccordionReorderIntegration|NativeAccordionLiftIntegration|NativeAccordionShiftIntegration|NativeAccordionStatesIntegration|NativeAccordionPlaceholderIntegration|NativeAccordionFloatingIntegration|NativeCardPaintIntegration|NativeCardStatesIntegration|NativeCardLifecycleIntegration|NativeListMethodsIntegration|NativeListPaintIntegration|NativeListStatesIntegration|NativeListTooltipIntegration|NativeBottomSheetMotionIntegration|NativeBottomSheetPaintIntegration|NativeDialogMotionIntegration|NativeDialogPaintIntegration|NativeModalStackIntegration|NativeSideSheetMotionIntegration|NativeSideSheetPaintIntegration|NativeAvatarIntegration|NativeSwitchPaintIntegration|NativeSwitchStatesIntegration|NativeCheckboxPaintIntegration|NativeCheckboxStatesIntegration|NativeChipPaintIntegration|NativeChipStatesIntegration|NativeButtonPaintIntegration|NativeButtonStatesIntegration|NativeRadioPaintIntegration|NativeRadioStatesIntegration|NativeTextFieldPaintIntegration|NativeTextFieldStatesIntegration|NativeNumberFieldPaintIntegration|NativeNumberFieldStatesIntegration|NativeOTPFieldPaintIntegration|NativeOTPFieldStatesIntegration|NativeOrgChartPaintIntegration|NativeOrgChartStatesIntegration|NativeThemeIntegration) ;;
    *) echo "Unknown native view fixture: $fixture" >&2; exit 1 ;;
  esac
  swiftc -parse-as-library -module-cache-path "$module_cache_dir" \
    -I "$library_dir/Modules" "$package_dir/Tests/$fixture.swift" \
    "$library_dir"/AWCUI.build/*.o -o "$build_dir/$fixture"
  "$build_dir/$fixture"
  if [ "$fixture" = NativeFabMenuViewIntegration ]; then
    "$build_dir/$fixture" --interactions-only --native-pointer
  fi
done
